const esc = v => String(v ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={overview:'M3 12h4l3-8 4 16 3-8h4',nics:'M8 3h8v6H8z M12 9v5 M4 14h16 M4 14v6 M12 14v6 M20 14v6',config:'M4 6h16 M4 12h16 M4 18h16 M8 3v6 M16 9v6 M10 15v6',packets:'M4 4h16v16H4z M4 9h16 M9 9v11',runtime:'M5 4h14v16H5z M8 8h8 M8 12h8 M8 16h5',sun:'M12 8.5a3.5 3.5 0 1 0 0 7 3.5 3.5 0 1 0 0-7M12 2.5v2M12 19.5v2M4.6 4.6 6 6M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4',moon:'M20 15.2A8.2 8.2 0 0 1 8.8 4a8.4 8.4 0 1 0 11.2 11.2Z',check:'M5 12l4 4L19 6',arrow:'M5 12h14 M13 6l6 6-6 6',clock:'M12 8v4l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',pause:'M9 5v14 M15 5v14',play:'M7 4l13 8-13 8z',stop:'M6 6h12v12H6z',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',alert:'M12 3L2 21h20L12 3z M12 9v5 M12 17v1',refresh:'M20 7v5h-5 M4 17v-5h5 M5.5 7a8 8 0 0 1 13-2L20 7 M4 17l1.5 2a8 8 0 0 0 13-2',copy:'M9 9h11v12H9z M15 9V3H3v12h6',back:'M19 12H5 M11 6l-6 6 6 6'};
const icon=(name)=>`<svg class="od-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.clock}"/></svg>`;
